    function toRadians(deg) { return (deg * Math.PI) / 180; }
    function toDegrees(rad) { return (rad * 180) / Math.PI; }
    function clamp(val, min, max) { return Math.max(min, Math.min(max, val)); }
    function randomBetween(min, max) { return min + Math.random() * (max - min); }

    function movePoint(lat, lon, meters, heading) {
        const radius = 6371000;
        const distance = meters / radius;
        const bearing = toRadians(heading);
        const startLat = toRadians(lat);
        const startLon = toRadians(lon);

        const endLat = Math.asin(
            Math.sin(startLat) * Math.cos(distance) +
            Math.cos(startLat) * Math.sin(distance) * Math.cos(bearing)
        );

        const endLon =
            startLon +
            Math.atan2(
                Math.sin(bearing) * Math.sin(distance) * Math.cos(startLat),
                Math.cos(distance) - Math.sin(startLat) * Math.sin(endLat)
            );

        return {
            lat: toDegrees(endLat),
            lon: ((toDegrees(endLon) + 540) % 360) - 180
        };
    }

