    window.addEventListener('keydown', (e) => {
        if (e.key === 'x' || e.key === 'X') {
            const active = document.activeElement;
            if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable)) return;
            togglePanel();
        }
    });

